<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>智能任务管理器</title>
    <link rel="stylesheet" href="style.css">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet">
</head>
<body>
    <div class="container">
        <!-- 头部 -->
        <header class="header">
            <h1><i class="fas fa-tasks"></i> 智能任务管理器</h1>
            <div class="stats">
                <span class="stat total-tasks"><i class="fas fa-list"></i> <span>0</span></span>
                <span class="stat completed-tasks"><i class="fas fa-check-circle"></i> <span>0</span></span>
            </div>
        </header>

        <!-- 添加任务区域 -->
        <div class="add-task-section">
            <div class="input-group">
                <input type="text" id="taskInput" placeholder="输入你的任务... (按Enter添加)">
                <select id="prioritySelect">
                    <option value="low">低优先级</option>
                    <option value="medium" selected>中优先级</option>
                    <option value="high">高优先级</option>
                </select>
                <button id="addBtn"><i class="fas fa-plus"></i> 添加</button>
            </div>
        </div>

        <!-- 任务列表 -->
        <div class="tasks-container">
            <div class="tabs">
                <button class="tab active" data-tab="all">全部 <span class="tab-count" data-tab="all-count">0</span></button>
                <button class="tab" data-tab="pending">待完成 <span class="tab-count" data-tab="pending-count">0</span></button>
                <button class="tab" data-tab="completed">已完成 <span class="tab-count" data-tab="completed-count">0</span></button>
            </div>

            <div class="tasks-list" id="allTasks">
                <!-- 任务将动态生成 -->
            </div>
        </div>

        <!-- 底部操作 -->
        <div class="actions">
            <button id="clearCompleted" class="btn-secondary">
                <i class="fas fa-trash"></i> 清除已完成
            </button>
            <button id="exportTasks" class="btn-primary">
                <i class="fas fa-download"></i> 导出任务
            </button>
        </div>
    </div>

    <!-- 拖拽提示 -->
    <div class="drag-hint" id="dragHint">
        <i class="fas fa-grip-vertical"></i> 拖拽调整顺序
    </div>

    <script src="script.js"></script>
</body>
</html>
