### JavaScript (script.js)
```javascript
class TaskManager {
    constructor() {
        this.tasks = JSON.parse(localStorage.getItem('tasks')) || [];
        this.currentTab = 'all';
        this.init();
    }

    init() {
        this.bindEvents();
        this.render();
        this.updateStats();
    }

    bindEvents() {
        // 添加任务
        document.getElementById('addBtn').addEventListener('click', () => this.addTask());
        document.getElementById('taskInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') this.addTask();
        });

        // Tab切换
        document.querySelectorAll('.tab').forEach(tab => {
            tab.addEventListener('click', (e) => this.switchTab(e.target.dataset.tab));
        });

        // 批量操作
        document.getElementById('clearCompleted').addEventListener('click', () => this.clearCompleted());
        document.getElementById('exportTasks').addEventListener('click', () => this.exportTasks());

        // 显示拖拽提示
        document.querySelector('.tasks-list').addEventListener('mouseenter', () => {
            document.getElementById('dragHint').style.display = 'flex';
        });
        document.querySelector('.tasks-list').addEventListener('mouseleave', () => {
            document.getElementById('dragHint').style.display = 'none';
        });
    }

    addTask() {
        const input = document.getElementById('taskInput');
        const priority = document.getElementById('prioritySelect').value;
        const text = input.value.trim();

        if (!text) return;

        const task = {
            id: Date.now(),
            text,
            priority,
            completed: false,
            createdAt: new Date().toISOString()
        };

        this.tasks.unshift(task);
        input.value = '';
        this.save();
        this.render();
        this.updateStats();
    }

    toggleTask(id) {
        const task = this.tasks.find(t => t.id === id);
        if (task) {
            task.completed = !task.completed;
            this.save();
            this.render();
            this.updateStats();
        }
    }

    deleteTask(id) {
        this.tasks = this.tasks.filter(t => t.id !== id);
        this.save();
        this.render();
        this.updateStats();
    }

    switchTab(tab) {
        this.currentTab = tab;
        document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        document.querySelector(`[data-tab="${tab}"]`).classList.add('active');
        this.render();
    }

    clearCompleted() {
        this.tasks = this.tasks.filter(task => !task.completed);
        this.save();
        this.render();
        this.updateStats();
    }

    exportTasks() {
        const dataStr = JSON.stringify(this.tasks, null, 2);
        const dataBlob = new Blob([dataStr], {type: 'application/json'});
        const url = URL.createObjectURL(dataBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `tasks-${new Date().toISOString().split('T')[0]}.json`;
        link.click();
    }

    getFilteredTasks() {
        switch (this.currentTab) {
            case 'pending': return this.tasks.filter(task => !task.completed);
            case 'completed': return this.tasks.filter(task => task.completed);
            default: return this.tasks;
        }
    }

    render() {
        const container = document.getElementById('allTasks');
        const tasks = this.getFilteredTasks();

        container.innerHTML = tasks.map(task => `
            <div class="task-item" draggable="true" data-id="${task.id}">
                <div class="task-drag-handle">
                    <i class="fas fa-grip-vertical"></i>
                </div>
                <div class="task-checkbox ${task.completed ? 'checked' : ''}" 
                     onclick="taskManager.toggleTask(${task.id})"></div>
                <div class="task-content">
                    <div class="task-text ${task.completed ? 'completed' : ''}">${this.escapeHtml(task.text)}</div>
                    <div class="priority-badge priority-${task.priority}">
                        ${task.priority === 'high' ? '🔥 高优先' : 
                          task.priority === 'medium' ? '⭐ 中优先' : '✅ 低优先'}
                    </div>
                </div>
                <div class="task-delete" onclick="taskManager.deleteTask(${task.id})">
                    <i class="fas fa-times"></i>
                </div>
            </div>
        `).join('');

        this.setupDragAndDrop();
        this.updateTabCounts();
    }

    setupDragAndDrop() {
        const taskItems = document.querySelectorAll('.task-item');

        taskItems.forEach(item => {
            item.addEventListener('dragstart', (e) => {
                e.target.classList.add('dragging');
            });

            item.addEventListener('dragend', (e) => {
                e.target.classList.remove('dragging');
            });

            item.addEventListener('dragover', (e) => {
                e.preventDefault();
            });

            item.addEventListener('drop', (e) => {
                e.preventDefault();
                const draggedId = parseInt(e.target.closest('.task-item').dataset.id);
                const targetId = parseInt(item.dataset.id);

                if (draggedId !== targetId) {
                    this.reorderTasks(draggedId, targetId);
                }
            });
        });
    }

    reorderTasks(draggedId, targetId) {
        const draggedIndex = this.tasks.findIndex(t => t.id === draggedId);
        const targetIndex = this.tasks.findIndex(t => t.id === targetId);

        const [draggedTask] = this.tasks.splice(draggedIndex, 1);
        this.tasks.splice(targetIndex, 0, draggedTask);

        this.save();
        this.render();
    }

    updateStats() {
        const total = this.tasks.length;
        const completed = this.tasks.filter(t => t.completed).length;

        document.querySelector('.total-tasks span').textContent = total;
        document.querySelector('.completed-tasks span').textContent = completed;
    }

    updateTabCounts() {
        const total = this.tasks.length;
        const pending = this.tasks.filter(t => !t.completed).length;
        const completed = this.tasks.filter(t => t.completed).length;

        document.querySelector('[data-tab="all-count"]').textContent = total;
        document.querySelector('[data-tab="pending-count"]').textContent = pending;
        document.querySelector('[data-tab="completed-count"]').textContent = completed;
    }

    save() {
        localStorage.setItem('tasks', JSON.stringify(this.tasks));
    }

    escapeHtml(text) {
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        };
        return text.replace(/[&<>"']/g, m => map[m]);
    }
}

// 初始化应用
const taskManager = new TaskManager();
```

